# ===================== CONFIGURATION =====================
# Render > Environment variables is preferred. For local testing, a .env file
# beside this script is also supported (KEY=VALUE, one per line).
# Never commit/share a .env file containing real tokens or API keys.
def _load_local_env_file():
    env_file = Path(__file__).resolve().parent / '.env'
    if not env_file.is_file():
        return
    try:
        for raw_line in env_file.read_text(encoding='utf-8').splitlines():
            line = raw_line.strip()
            if not line or line.startswith('#') or '=' not in line:
                continue
            key, value = line.split('=', 1)
            key, value = key.strip(), value.strip().strip('\"').strip("'")
            if key and value and key not in os.environ:
                os.environ[key] = value
    except OSError as exc:
        print(f'WARNING: Could not read .env file: {exc}')

_load_local_env_file()

# Put these in Render Environment Variables. Aliases support older deployments.
MANAGER_BOT_TOKEN = (os.getenv('MANAGER_BOT_TOKEN') or os.getenv('BOT_TOKEN') or '').strip()
OWNER_ADMIN_ID = (os.getenv('OWNER_ADMIN_ID') or os.getenv('ADMIN_ID') or '').strip()
FAMGATEWAY_API_KEY = (os.getenv('FAMGATEWAY_API_KEY') or '').strip()
FAMGATEWAY_UPI_ID = (os.getenv('FAMGATEWAY_UPI_ID') or '').strip()
CLONE_PRICE_INR = (os.getenv('CLONE_PRICE_INR') or '99').strip()
CLONE_ENCRYPTION_KEY = (os.getenv('CLONE_ENCRYPTION_KEY') or '').strip()
# =========================================================

ROOT=Path(__file__).resolve().parent
DATA=ROOT/'clone_data'; DATA.mkdir(exist_ok=True)
DB=ROOT/'clone_manager.db'
BOT_TOKEN=MANAGER_BOT_TOKEN
try: ADMIN_ID=int(OWNER_ADMIN_ID)
except ValueError: ADMIN_ID=0
GATEWAY_KEY=FAMGATEWAY_API_KEY
UPI_ID=FAMGATEWAY_UPI_ID
QR_URL='https://famgateway.in/api/qr.php'
VERIFY_URL='https://famgateway.in/api/verify-order.php'
STATUS_URL='https://famgateway.in/api/checkout-status.php'
DEFAULT_PRICE=float(CLONE_PRICE_INR or '99')
FERNET_KEY=CLONE_ENCRYPTION_KEY
if not FERNET_KEY:
    # Save a generated key beside the app for local continuity. On Render, set
    # CLONE_ENCRYPTION_KEY explicitly and keep it unchanged across deployments.
    key_file = ROOT / '.clone_encryption_key'
    try:
        if key_file.exists():
            FERNET_KEY = key_file.read_text(encoding='utf-8').strip()
        else:
            FERNET_KEY = Fernet.generate_key().decode()
            key_file.write_text(FERNET_KEY, encoding='utf-8')
            try: key_file.chmod(0o600)
            except OSError: pass
        log_message = 'Using local encryption-key file; configure CLONE_ENCRYPTION_KEY in Render for persistent deployments.'
        print('WARNING:', log_message)
    except OSError:
        raise RuntimeError('Set CLONE_ENCRYPTION_KEY in Render Environment Variables to a valid Fernet key.')
try:
    fernet=Fernet(FERNET_KEY.encode())
except (ValueError, TypeError) as exc:
    raise RuntimeError('CLONE_ENCRYPTION_KEY is invalid. Use a Fernet key and keep it unchanged between deploys.') from exc
logging.basicConfig(level=logging.INFO,format='%(asctime)s %(levelname)s %(message)s')
log=logging.getLogger('aryan-clone-manager')
bot=Bot(BOT_TOKEN) if BOT_TOKEN else None
dp=Dispatcher()

class Flow(StatesGroup):
    waiting_amount=State(); waiting_token=State(); waiting_username=State(); waiting_shop=State(); waiting_admin_id=State(); waiting_contact=State()
    waiting_wallet_amount=State(); waiting_channel_username=State(); waiting_channel_url=State(); waiting_admin_channel=State()

def db():
    c=sqlite3.connect(DB,timeout=30); c.row_factory=sqlite3.Row; return c

def init_db():
    with db() as c:
        c.execute('CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY,value TEXT NOT NULL)')
        c.execute("CREATE TABLE IF NOT EXISTS orders (id TEXT PRIMARY KEY,user_id INTEGER,amount REAL,status TEXT,created INTEGER,qr_url TEXT,config_json TEXT,clone_id TEXT,kind TEXT DEFAULT 'panel')")
        c.execute("CREATE TABLE IF NOT EXISTS clones (clone_id TEXT PRIMARY KEY,user_id INTEGER,username TEXT,shop_name TEXT,status TEXT,created INTEGER,process_pid INTEGER,config_json TEXT,kind TEXT DEFAULT 'panel')")
        c.execute('CREATE TABLE IF NOT EXISTS wallets (user_id INTEGER PRIMARY KEY, balance REAL NOT NULL DEFAULT 0)')
        c.execute('CREATE TABLE IF NOT EXISTS wallet_ledger (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER,amount REAL,kind TEXT,order_id TEXT,created INTEGER)')
        for table, coldef in [('orders', "kind TEXT DEFAULT 'panel'"), ('clones', "kind TEXT DEFAULT 'panel'")]:
            try: c.execute(f'ALTER TABLE {table} ADD COLUMN {coldef}')
            except sqlite3.OperationalError: pass
        c.execute('INSERT OR IGNORE INTO settings(key,value) VALUES("clone_price",?)',(str(DEFAULT_PRICE),))
        c.execute('INSERT OR IGNORE INTO settings(key,value) VALUES("panel_price",?)',(str(DEFAULT_PRICE),))
        c.execute('INSERT OR IGNORE INTO settings(key,value) VALUES("hosting_price","149")')
        c.execute('INSERT OR IGNORE INTO settings(key,value) VALUES("channel_username","")')
        c.execute('INSERT OR IGNORE INTO settings(key,value) VALUES("channel_url","")')

def setting(k,default=''):
    with db() as c:
        r=c.execute('SELECT value FROM settings WHERE key=?',(k,)).fetchone(); return r['value'] if r else default

def set_setting(k,v):
    with db() as c: c.execute('INSERT OR REPLACE INTO settings(key,value) VALUES(?,?)',(k,str(v)))

def is_admin(uid): return uid==ADMIN_ID

def wallet_balance(uid):
    with db() as c:
        c.execute('INSERT OR IGNORE INTO wallets(user_id,balance) VALUES(?,0)', (uid,))
        r=c.execute('SELECT balance FROM wallets WHERE user_id=?',(uid,)).fetchone()
        return float(r['balance'] or 0)

def menu():
    rows=[[InlineKeyboardButton(text='🔥 Free Fire Panel Bot',callback_data='buy_panel')],[InlineKeyboardButton(text='🖥️ Hosting Bot',callback_data='buy_hosting')],[InlineKeyboardButton(text='💰 Add Balance',callback_data='add_balance'),InlineKeyboardButton(text='💳 My Balance',callback_data='wallet_view')]]
    channel_url=setting('channel_url','').strip()
    if channel_url: rows.append([InlineKeyboardButton(text='📢 Updates Channel',url=channel_url)])
    rows.append([InlineKeyboardButton(text='📞 Admin Support',url=os.getenv('ADMIN_CONTACT_URL','https://t.me/XLARYAN_0100'))])
    return InlineKeyboardMarkup(inline_keyboard=rows)

def admin_menu():
    return InlineKeyboardMarkup(inline_keyboard=[[InlineKeyboardButton(text='🔥 Set Panel Price',callback_data='adm_panel_price'),InlineKeyboardButton(text='🖥️ Set Hosting Price',callback_data='adm_host_price')],[InlineKeyboardButton(text='📊 Stats',callback_data='adm_stats'),InlineKeyboardButton(text='🤖 Orders/Clones',callback_data='adm_clones')],[InlineKeyboardButton(text='📢 Set Channel',callback_data='adm_channel')]])

async def fam_create(amount,user_id):
    if not GATEWAY_KEY: return None,'FAMGATEWAY_API_KEY environment variable set nahi hai.'
    try:
        async with aiohttp.ClientSession() as s:
            async with s.get(QR_URL,params={'api_key':GATEWAY_KEY,'amount':f'{amount:.2f}','customer_name':f'Telegram User {user_id}'},headers={'Accept':'application/json'},timeout=aiohttp.ClientTimeout(total=20)) as r:
                data=await r.json(content_type=None)
                if r.status!=200 or str(data.get('status','')).lower()!='success': return None,str(data.get('message') or f'Gateway HTTP {r.status}')
                d=data.get('data') or {}
                if not d.get('order_id') or not d.get('qr_url'): return None,'Gateway response mein order_id/qr_url missing hai.'
                return {'order_id':str(d['order_id']),'qr_url':str(d['qr_url'])},None
    except Exception as e: return None,f'Gateway error: {e}'

async def fam_verify(order_id,expected_amount):
    if not GATEWAY_KEY: return False
    async with aiohttp.ClientSession() as s:
        for url,params,headers in [
            (VERIFY_URL,{'order_id':order_id},{'X-Api-Key':GATEWAY_KEY,'Accept':'application/json'}),
            (VERIFY_URL,{'api_key':GATEWAY_KEY,'order_id':order_id},{'Accept':'application/json'}),
            (STATUS_URL,{'order_id':order_id},{'Accept':'application/json'})]:
            try:
                async with s.get(url,params=params,headers=headers,timeout=aiohttp.ClientTimeout(total=15)) as r:
                    data=await r.json(content_type=None)
                d=data.get('data') if isinstance(data,dict) and isinstance(data.get('data'),dict) else data
                status=str(d.get('status','')).lower() if isinstance(d,dict) else ''
                paid=(status in {'success','paid','completed','confirmed'} or (isinstance(d,dict) and (d.get('is_paid') is True or d.get('paid') is True)))
                returned=str(d.get('order_id') or data.get('order_id') or '') if isinstance(d,dict) else ''
                amount=d.get('amount') if isinstance(d,dict) else None
                if paid and (not returned or returned==order_id) and (amount is None or abs(float(amount)-expected_amount)<0.02): return True
            except Exception: pass
    return False

