@dp.callback_query(F.data.startswith('paycheck:'))
async def check_payment(q:CallbackQuery,state:FSMContext):
    oid=q.data.split(':',1)[1]
    with db() as c: row=c.execute('SELECT user_id,amount,status,kind FROM orders WHERE id=?',(oid,)).fetchone()
    if not row or row['user_id']!=q.from_user.id: return await q.answer('Order invalid hai.',show_alert=True)
    if row['status']=='paid': return await q.answer('Payment already verified.',show_alert=True)
    if not await fam_verify(oid,float(row['amount'])): return await q.answer('Payment abhi verify nahi hua. Thodi der baad try karein.',show_alert=True)
    with db() as c:
        updated=c.execute('UPDATE orders SET status="paid" WHERE id=? AND status="pending"',(oid,))
        if updated.rowcount != 1:
            return await q.answer('Order already processed.',show_alert=True)
        if row['kind']=='wallet':
            c.execute('INSERT OR IGNORE INTO wallets(user_id,balance) VALUES(?,0)',(q.from_user.id,))
            c.execute('UPDATE wallets SET balance=balance+? WHERE user_id=?',(float(row['amount']),q.from_user.id))
            c.execute('INSERT INTO wallet_ledger(user_id,amount,kind,order_id,created) VALUES(?,?,?,?,?)',(q.from_user.id,float(row['amount']),'topup',oid,int(time.time())))
    if row['kind']=='wallet':
        await q.message.answer(f'✅ Payment verified! ₹{float(row["amount"]):.2f} wallet mein add ho gaye.\n💰 New balance: ₹{wallet_balance(q.from_user.id):.2f}',reply_markup=menu())
    else:
        await begin_product_setup(q.message,state,oid,row['kind'] or 'panel')
    await q.answer('Verified')

