@dp.message(Flow.waiting_contact)
async def contact_step(m:Message,state:FSMContext):
    contact=(m.text or '').strip()
    if not (contact.startswith('@') or contact.startswith('https://t.me/') or re.fullmatch(r'\+?[0-9 ()-]{7,20}',contact)): return await m.answer('Contact @username, t.me link, ya phone number ho sakta hai.')
    d=await state.get_data(); token=d['token']; clone_id=d['clone_id']; cdir=DATA/clone_id
    cfg={'token':token,'username':d['bot_username'],'shop_name':d['shop_name'],'photo_path':'','admin_id':int(d['admin_id']),'admin_contact':contact,'owner_user_id':m.from_user.id,'order_id':d['order_id']}
    # Encrypt sensitive configuration at rest. Only decrypt when starting the worker.
    encrypted=fernet.encrypt(json.dumps(cfg).encode()).decode()
    try:
        proc=start_worker(clone_id,cfg)
    except Exception as e:
        log.exception('worker start failed')
        return await m.answer(f'Configuration save ho gayi lekin worker start nahi hua: {e}. Hosting logs check karein; /setup se retry support admin se lein.')
    with db() as c:
        c.execute('INSERT INTO clones(clone_id,user_id,username,shop_name,status,created,process_pid,config_json,kind) VALUES(?,?,?,?,?,?,?,?,?)',(clone_id,m.from_user.id,cfg['username'],cfg['shop_name'],'running',int(time.time()),proc.pid,encrypted,'panel'))
        c.execute('UPDATE orders SET clone_id=? WHERE id=?',(clone_id,d['order_id']))
    await state.clear()
    await m.answer(f'🎉 <b>Clone setup complete!</b>\n\nShop: {cfg["shop_name"]}\nBot: @{cfg["username"]}\nStatus: running\nClone ID: <code>{clone_id}</code>\n\nOpen your bot: https://t.me/{cfg["username"]}\n\nNote: Free hosting par 24/7 uptime guaranteed nahi hota.',parse_mode='HTML')
    try: await bot.send_message(ADMIN_ID,f'🆕 Clone created\nOwner: {m.from_user.id}\nShop: {cfg["shop_name"]}\nBot: @{cfg["username"]}\nClone: {clone_id}')
    except Exception: pass

def start_worker(clone_id,cfg):
    worker=DATA/'clone_worker_runtime.py'
    if not worker.exists(): worker.write_text(WORKER_SOURCE, encoding='utf-8')
    env=os.environ.copy()
    env.update({'BOT_TOKEN':cfg['token'],'BOT_USERNAME':cfg['username'],'ADMIN_ID':str(cfg['admin_id']),'ADMIN_CONTACT':cfg['admin_contact'],'SHOP_NAME':cfg['shop_name'],'PANEL_PHOTO_PATH':'','DB_PATH':str((DATA/clone_id/'shop.db').resolve()),'FAMGATEWAY_API_KEY':GATEWAY_KEY,'RESELLER_API_KEY':''})
    logpath=DATA/clone_id/'worker.log'
    f=open(logpath,'a',encoding='utf-8')
    proc=subprocess.Popen([sys.executable,str(worker)],cwd=str(ROOT),env=env,stdout=f,stderr=subprocess.STDOUT,start_new_session=True)
    return proc

def start_host_worker(clone_id,cfg):
    cdir=DATA/clone_id; cdir.mkdir(parents=True,exist_ok=True)
    source=zlib.decompress(base64.b85decode(HOSTING_SOURCE_Z85.encode())).decode('utf-8')
    runtime=cdir/'hosting_runtime.py'
    runtime.write_text(source,encoding='utf-8')
    env=os.environ.copy()
    env.update({'BOT_TOKEN':cfg['token'],'ADMIN_ID':str(cfg['admin_id']),'OWNER_ID':str(cfg['admin_id']),'CHANNEL_LINK':cfg['channel_username'],'CHANNEL_URL':cfg['channel_url']})
    logpath=cdir/'hosting_worker.log'; f=open(logpath,'a',encoding='utf-8')
    return subprocess.Popen([sys.executable,str(runtime)],cwd=str(cdir),env=env,stdout=f,stderr=subprocess.STDOUT,start_new_session=True)

