async def myclone(m:Message):
    with db() as c: rows=c.execute('SELECT clone_id,username,shop_name,status,kind FROM clones WHERE user_id=? ORDER BY created DESC',(m.from_user.id,)).fetchall()
    if not rows: return await m.answer('Aapke account par koi clone nahi mila.')
    await m.answer('\n'.join(f'{r["shop_name"]} — @{r["username"]} — {r["status"]} — {r["kind"]} — ID {r["clone_id"]}' for r in rows))

async def main():
    if not BOT_TOKEN:
        raise RuntimeError('BOT TOKEN MISSING: Render > your service > Environment mein MANAGER_BOT_TOKEN add karein aur value mein BotFather ka main bot token daalein. Save Changes ke baad redeploy karein. Token ko code/chat mein share na karein.')
    if ADMIN_ID<=0:
        raise RuntimeError('ADMIN ID MISSING: Render Environment mein OWNER_ADMIN_ID ke value mein apni numeric Telegram user ID daalein (username nahi), phir Save Changes/redeploy karein.')
    if not GATEWAY_KEY: log.warning('FAMGATEWAY_API_KEY missing: payments will not work until configured')
    init_db()
    # Resume previously configured clones after a host restart when persistent storage is available.
    with db() as c:
        rows=c.execute('SELECT clone_id,config_json,kind FROM clones WHERE status="running"').fetchall()
    for row in rows:
        try:
            cfg=json.loads(fernet.decrypt(row['config_json'].encode()).decode())
            proc=start_host_worker(row['clone_id'],cfg) if row['kind']=='hosting' else start_worker(row['clone_id'],cfg)
            with db() as c: c.execute('UPDATE clones SET process_pid=? WHERE clone_id=?',(proc.pid,row['clone_id']))
        except Exception:
            log.exception('Could not restart clone %s',row['clone_id'])
    await dp.start_polling(bot)

if __name__=='__main__':
    asyncio.run(main())
